        "consentPageSubheader2": "HIPAA Authorization",
        "consentPageBody6": "This allows Connect to access your health records. Please review it carefully. Once you have read this form and all of your questions have been answered, scroll down to electronically sign the form if you want to join Connect. You do not need to download the HIPAA Authorization to join the study.",
        "consentPageBody7": "Key points in the HIPAA Authorization that you are agreeing to are:",
        "consentPageBody7List": "<li>I know the following information may be gathered from my electronic health records:<ul><li>Health information connected to my medical history and current and future health care. The information includes but is not limited to: test results; medical procedures; images; dental health records; and medicines I take.</li><li>Treatment information, including medicines for certain conditions like depression.</li><li>Sexual health and sexually transmitted infection information, including HIV/AIDS status.</li><li>Information about genetic conditions.</li></ul></li>",
        "consentPageBody8": "By clicking “Yes, I agree to join Connect” and typing your name, you confirm:",
        "consentPageBody9": "I have read the consent form and HIPAA Authorization and I understand the information in these forms. All of my questions have been answered. I freely and willingly choose to take part in the Connect for Cancer Prevention Study and I authorize my health care providers and other organizations to share my electronic health records with the Connect for Cancer Prevention Study.",
        "consentPageAgree": "Yes, I agree to join Connect",
        "consentPageFormFirstName": "First Name<span class=\"required\">*</span>",
        "consentPageFormMiddleName": "Middle Name<span></span>",
        "consentPageFormLastName": "Last Name<span class=\"required\">*</span>",
        "consentPageFormSuffixLabel": "Suffix<span></span>",
        "consentPageFormSuffixList": "<option value=\"\">-Select-</option><option value=\"612166858\">Jr.</option><option value=\"255907182\">Sr.</option><option value=\"226924545\">I</option><option value=\"270793412\">II</option><option value=\"959021713\">III</option><option value=\"643664527\">2nd</option><option value=\"537892528\">3rd</option>",
        "consentPageFormLegalName": "Please enter your legal name. If you are a member of Kaiser Permanente, please enter your first and last name exactly as it appears on your Kaiser Permanente ID card.",
        "submitButtonText": "Submit",
